solutions.naive:
class Solution:
    def removeStars(self, s: str) -> str:
        chars = list(s)
        for i, ch in enumerate(chars):
            if ch == '*':
                j = i - 1
                while j >= 0 and chars[j] == '':
                    j -= 1
                chars[j] = ''
                chars[i] = ''
        return "".join(chars)

solutions.better:
class Solution:
    def removeStars(self, s: str) -> str:
        stack = []
        for ch in s:
            if ch == '*':
                stack.pop()
            else:
                stack.append(ch)
        return "".join(stack)

