class Solution:
    def removeStars(self, s: str) -> str:
        skip = 0
        kept = []
        for ch in reversed(s):
            if ch == '*':
                skip += 1
            elif skip:
                skip -= 1
            else:
                kept.append(ch)
        return "".join(reversed(kept))

